def compute_confidence(best_score, second_score, known: bool):
    if not known:
        conf=min(0.35, 0.15 + 0.05*max(best_score,0))
        return round(conf, 2)
    margin=max(best_score-second_score, 0) if second_score>=0 else best_score
    base=0.5 + 0.07*min(best_score,6.0)
    if best_score<2.0:
        base-=0.05
    if margin<0.5:
        base-=0.07
    if margin<0.2:
        base-=0.06
    if best_score>4.0:
        base+=0.03
    base=max(0.6, min(base, 0.97))
    return round(base, 2)

